   445  /*
   446   * Check if a key exists in the map using the 'offset' as an index to define
   447   * which element needs to start looking from
   448   */
   449  static inline int key_exists_in_map(msgpack_object key, msgpack_object map, int offset)
   450  {
   451      int i;
   452      msgpack_object p;
   453
   454      if (key.type != MSGPACK_OBJECT_STR) {
   455          return FLB_FALSE;
   456      }
   457
   458      for (i = offset; i < map.via.map.size; i++) {
   459          p = map.via.map.ptr[i].key;
   460          if (p.type != MSGPACK_OBJECT_STR) {
   461              continue;
   462          }
   463
   464          if (key.via.str.size != p.via.str.size) {
   465              continue;
   466          }
   467
   468          if (memcmp(key.via.str.ptr, p.via.str.ptr, p.via.str.size) == 0) {
   469              return FLB_TRUE;
   470          }
   471      }
   472
   473      return FLB_FALSE;
   474  }
