   476  static int msgpack2json(char *buf, int *off, size_t left,
   477                          const msgpack_object *o)
   478  {
   479      int i;
   480      int dup;
   481      int ret = FLB_FALSE;
   482      int loop;
   483      int packed;
   484
   485      switch(o->type) {
   486      case MSGPACK_OBJECT_NIL:
   487          ret = try_to_write(buf, off, left, "null", 4);
   488          break;
   489
   490      case MSGPACK_OBJECT_BOOLEAN:
   491          ret = try_to_write(buf, off, left,
   492                             (o->via.boolean ? "true":"false"),0);
   493
   494          break;
   495
   496      case MSGPACK_OBJECT_POSITIVE_INTEGER:
   497          {
   498              char temp[32] = {0};
   499              i = snprintf(temp, sizeof(temp)-1, "%"PRIu64, o->via.u64);
   500              ret = try_to_write(buf, off, left, temp, i);
   501          }
   502          break;
   503
   504      case MSGPACK_OBJECT_NEGATIVE_INTEGER:
   505          {
   506              char temp[32] = {0};
   507              i = snprintf(temp, sizeof(temp)-1, "%"PRId64, o->via.i64);
   508              ret = try_to_write(buf, off, left, temp, i);
   509          }
   510          break;
   511      case MSGPACK_OBJECT_FLOAT32:
   512      case MSGPACK_OBJECT_FLOAT64:
   513          {
   514              char temp[512] = {0};
   515              if (o->via.f64 == (double)(long long int)o->via.f64) {
   516                  i = snprintf(temp, sizeof(temp)-1, "%.1f", o->via.f64);
   517              }
   518              else {
   519                  i = snprintf(temp, sizeof(temp)-1, "%.16g", o->via.f64);
   520              }
   521              ret = try_to_write(buf, off, left, temp, i);
   522          }
   523          break;
   524
   525      case MSGPACK_OBJECT_STR:
   526          if (try_to_write(buf, off, left, "\"", 1) &&
   527              (o->via.str.size > 0 ?
   528               try_to_write_str(buf, off, left, o->via.str.ptr, o->via.str.size)
   529               : 1/* nothing to do */) &&
   530              try_to_write(buf, off, left, "\"", 1)) {
   531              ret = FLB_TRUE;
   532          }
   533          break;
   534
   535      case MSGPACK_OBJECT_BIN:
   536          if (try_to_write(buf, off, left, "\"", 1) &&
   537              (o->via.bin.size > 0 ?
   538               try_to_write_str(buf, off, left, o->via.bin.ptr, o->via.bin.size)
   539                : 1 /* nothing to do */) &&
   540              try_to_write(buf, off, left, "\"", 1)) {
   541              ret = FLB_TRUE;
   542          }
   543          break;
   544
   545      case MSGPACK_OBJECT_EXT:
   546          if (!try_to_write(buf, off, left, "\"", 1)) {
   547              goto msg2json_end;
   548          }
   549          /* ext body. fortmat is similar to printf(1) */
   550          {
   551              char temp[32] = {0};
   552              int  len;
   553              loop = o->via.ext.size;
   554              for(i=0; i<loop; i++) {
   555                  len = snprintf(temp, sizeof(temp)-1, "\\x%02x", (char)o->via.ext.ptr[i]);
   556                  if (!try_to_write(buf, off, left, temp, len)) {
   557                      goto msg2json_end;
   558                  }
   559              }
   560          }
   561          if (!try_to_write(buf, off, left, "\"", 1)) {
   562              goto msg2json_end;
   563          }
   564          ret = FLB_TRUE;
   565          break;
   566
   567      case MSGPACK_OBJECT_ARRAY:
   568          loop = o->via.array.size;
   569
   570          if (!try_to_write(buf, off, left, "[", 1)) {
   571              goto msg2json_end;
   572          }
   573          if (loop != 0) {
   574              msgpack_object* p = o->via.array.ptr;
   575              if (!msgpack2json(buf, off, left, p)) {
   576                  goto msg2json_end;
   577              }
   578              for (i=1; i<loop; i++) {
   579                  if (!try_to_write(buf, off, left, ",", 1) ||
   580                      !msgpack2json(buf, off, left, p+i)) {
   581                      goto msg2json_end;
   582                  }
   583              }
   584          }
   585
   586          ret = try_to_write(buf, off, left, "]", 1);
   587          break;
   588
   589      case MSGPACK_OBJECT_MAP:
   590          loop = o->via.map.size;
   591          if (!try_to_write(buf, off, left, "{", 1)) {
   592              goto msg2json_end;
   593          }
   594          if (loop != 0) {
   595              msgpack_object k;
   596              msgpack_object_kv *p = o->via.map.ptr;
   597
   598              packed = 0;
   599              dup = FLB_FALSE;
   600
   601              k = o->via.map.ptr[0].key;
   602              for (i = 0; i < loop; i++) {
   603                  k = o->via.map.ptr[i].key;
   604                  dup = key_exists_in_map(k, *o, i + 1);
   605                  if (dup == FLB_TRUE) {
   606                      continue;
   607                  }
   608
   609                  if (packed > 0) {
   610                      if (!try_to_write(buf, off, left, ",", 1)) {
   611                          goto msg2json_end;
   612                      }
   613                  }
   614
   615                  if (
   616                      !msgpack2json(buf, off, left, &(p+i)->key) ||
   617                      !try_to_write(buf, off, left, ":", 1)  ||
   618                      !msgpack2json(buf, off, left, &(p+i)->val) ) {
   619                      goto msg2json_end;
   620                  }
   621                  packed++;
   622              }
   623          }
   624
   625          ret = try_to_write(buf, off, left, "}", 1);
   626          break;
   627
   628      default:
   629          flb_warn("[%s] unknown msgpack type %i", __FUNCTION__, o->type);
   630      }
   631
   632   msg2json_end:
   633      return ret;
   634  }
