   636  /**
   637   *  convert msgpack to JSON string.
   638   *  This API is similar to snprintf.
   639   *
   640   *  @param  json_str  The buffer to fill JSON string.
   641   *  @param  json_size The size of json_str.
   642   *  @param  data      The msgpack_unpacked data.
   643   *  @return success   ? a number characters filled : negative value
   644   */
   645  int flb_msgpack_to_json(char *json_str, size_t json_size,
   646                          const msgpack_object *obj)
   647  {
   648      int ret = -1;
   649      int off = 0;
   650
   651      if (json_str == NULL || obj == NULL) {
   652          return -1;
   653      }
   654
   655      ret = msgpack2json(json_str, &off, json_size - 1, obj);
   656      json_str[off] = '\0';
   657      return ret ? off: ret;
   658  }
